[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Destination,[ValidateSet('implementation','support-only')][string]$Profile='implementation')
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Destination);if(Test-Path $d){throw 'OPS_DESTINATION_EXISTS'};New-Item -ItemType Directory $d|Out-Null
$roles=@([ordered]@{id='ROLE-PROJECT-LEAD';name='Projektleitung';responsibility='Cutover und Entscheidung koordinieren'},[ordered]@{id='ROLE-PROCESS-OWNER';name='Process Owner';responsibility='Fachliche Kriterien entscheiden'},[ordered]@{id='ROLE-TECH-LEAD';name='Technical Lead';responsibility='Migration und Recovery steuern'},[ordered]@{id='ROLE-SUPPORT-LEAD';name='Support Lead';responsibility='Hypercare und Betrieb übernehmen'})
$evTypes=@('uat_exit','mock_cutover','go_no_go','hypercare_daily','fix','retest','backup_restore','support_acceptance','handover');$evidence=@();for($i=0;$i-lt$evTypes.Count;$i++){$hex=('{0:x}'-f($i+1));$evidence+=,[ordered]@{id=('EVD-OPS-{0:D2}'-f($i+1));type=$evTypes[$i];sha256=($hex*64);synthetic=$true;external_activity=$false}}
$tasks=@();$titles=@('UAT-Exit bestätigen','Datenfreeze und letzte Welle','Berechtigungen und Schnittstellen prüfen','Mock-Cutover auswerten','Go-live-Simulation durchführen','Betriebsübergabe vorbereiten');for($i=0;$i-lt$titles.Count;$i++){$dependencies=@();if($i-gt0){$dependencies=@(('CUT-{0:D2}'-f$i))};$tasks+=,[ordered]@{id=('CUT-{0:D2}'-f($i+1));sequence=$i+1;title=$titles[$i];owner_role=if($i-lt2){'ROLE-PROCESS-OWNER'}elseif($i-lt5){'ROLE-TECH-LEAD'}else{'ROLE-SUPPORT-LEAD'};depends_on=$dependencies;window=('T{0}'-f($i+1));entry_criteria=@('Vorherige Entscheidung und Evidence liegen vor');exit_criteria=@('Aufgabe ist fachlich und technisch geprüft');evidence_refs=@(('EVD-OPS-{0:D2}'-f([Math]::Min($i+1,9))));status='completed'}}
$days=@([ordered]@{id='DAY-01';day='2030-04-01';owner_role='ROLE-SUPPORT-LEAD';daily_evidence_ref='EVD-OPS-04';issues=@([ordered]@{id='HC-001';priority='P2';status='closed';diagnosis='Synthetische Buchungsabweichung';fix='Parameter kontrolliert korrigiert';retest_evidence_ref='EVD-OPS-06'});trend='improving';go_no_go='GO';next_step='Retest bestätigen';status='closed'},[ordered]@{id='DAY-02';day='2030-04-02';owner_role='ROLE-SUPPORT-LEAD';daily_evidence_ref='EVD-OPS-04';issues=@([ordered]@{id='HC-002';priority='P3';status='closed';diagnosis='Synthetische Anzeigeabweichung';fix='Darstellung geklärt';retest_evidence_ref='EVD-OPS-06'});trend='improving';go_no_go='GO';next_step='Supportannahme vorbereiten';status='closed'},[ordered]@{id='DAY-03';day='2030-04-03';owner_role='ROLE-SUPPORT-LEAD';daily_evidence_ref='EVD-OPS-04';issues=@();trend='stable';go_no_go='GO';next_step='Handover abschließen';status='closed'})
$x=[ordered]@{schema_version=1;product_id='spectra';profile=$Profile;program_id="SYN-OPS-$($Profile.ToUpperInvariant())";simulation_boundary='synthetic_non_production';roles=$roles;evidence=$evidence;uat_exit_ref='DEC-UAT-EXIT';cutover_tasks=$tasks;mock_cutover=[ordered]@{id='MOCK-CUTOVER-01';task_refs=@($tasks.id);planned_minutes=360;actual_minutes=390;variance_reason='Synthetische Retestschleife';evidence_refs=@('EVD-OPS-02');status='passed'};go_live_gate=[ordered]@{id='GATE-GO-LIVE';decision='GO';criteria_met=$true;open_p1=0;open_p2=0;owner_role='ROLE-PROJECT-LEAD';evidence_refs=@('EVD-OPS-01','EVD-OPS-03');conditions=@()};hypercare_days=$days;restart_plan=[ordered]@{id='RST-01';last_valid_state='Validiertes Backup vor Go-live-Simulation';backup_evidence_ref='EVD-OPS-07';abort_criteria=@('Integritätsprüfung schlägt fehl');resume_steps=@('Restore dry-run prüfen','Freigabe dokumentieren','Kontrolliert wiederaufnehmen');owner_role='ROLE-TECH-LEAD';decision='READY';status='tested'};support_acceptance=[ordered]@{id='SUP-ACCEPT-01';owner_role='ROLE-SUPPORT-LEAD';known_issues=@('Synthetische P3-Einschränkung dokumentiert');backlog_refs=@('HC-002');escalation_path='Support Lead zu Process Owner und Projektleitung';evidence_refs=@('EVD-OPS-08');accepted=$true};handover=[ordered]@{id='HND-01';support_acceptance_ref='SUP-ACCEPT-01';hypercare_exit=$true;open_p1=0;open_p2=0;evidence_refs=@('EVD-OPS-08','EVD-OPS-09');decision='ACCEPTED';known_limits=@('Keine reale Produktiv- oder Kundenevidence')}}
$utf8=[Text.UTF8Encoding]::new($false);[IO.File]::WriteAllText((Join-Path $d 'cutover-operations-handover.json'),(($x|ConvertTo-Json -Depth 30)+"`n"),$utf8);Write-Host "PASS: Synthetisches Cutover-/Betriebsprofil $Profile wurde deterministisch erzeugt."
